import{_ as t,a,o as r,a4 as o}from"./chunks/framework.-FZumj2l.js";const u=JSON.parse('{"title":"Product","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/shop/product/index.md","filePath":"api/graphql-api/shop/product/index.md","lastUpdated":1783420618000}'),s={name:"api/graphql-api/shop/product/index.md"};function i(n,e,d,h,p,c){return r(),a("div",null,e[0]||(e[0]=[o('<h1 id="product" tabindex="-1">Product <a class="header-anchor" href="#product" aria-label="Permalink to &quot;Product&quot;">​</a></h1><p>The Product menu is the storefront catalog — listing products, searching and filtering them, fetching one product&#39;s full detail, and (for booking products) reading available booking slots. It is the backbone of any product-listing page, search results page, or product-detail page.</p><h2 id="listing-searching-filtering" tabindex="-1">Listing, searching &amp; filtering <a class="header-anchor" href="#listing-searching-filtering" aria-label="Permalink to &quot;Listing, searching &amp; filtering&quot;">​</a></h2><p>The <strong>products</strong> query lists and filters the catalog (by category, type, price range, brand, attribute values, new / featured flags) with cursor pagination and sorting. The <strong>search products</strong> query runs a keyword search over the same surface. Both return the same product shape, so a listing page and a search results page can share rendering code. The <strong>single product</strong> query returns one product&#39;s full, type-aware detail.</p><h2 id="wishlist-compare-flags" tabindex="-1">Wishlist &amp; compare flags <a class="header-anchor" href="#wishlist-compare-flags" aria-label="Permalink to &quot;Wishlist &amp; compare flags&quot;">​</a></h2><p>When a customer Bearer token is sent, every product carries <code>isInWishlist</code> and <code>isInCompare</code> so the UI can highlight the wishlist / compare icon on each card without separately cross-referencing those lists. For guests both flags are always off.</p><h2 id="booking-slots" tabindex="-1">Booking slots <a class="header-anchor" href="#booking-slots" aria-label="Permalink to &quot;Booking slots&quot;">​</a></h2><p>For booking-type products, the <strong>booking slots</strong> query returns the available time slots a shopper can pick from before adding the product to the cart.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/shop/queries/get-products.html">Products</a></td><td><code>products</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/queries/search-products.html">Search Products</a></td><td><code>products</code> query (with search)</td></tr><tr><td><a href="/api/graphql-api/shop/queries/get-product.html">Single Product</a></td><td><code>product(id:)</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/queries/get-booking-slots.html">Booking Slots</a></td><td><code>bookingSlots</code> query</td></tr></tbody></table><p>These are public read endpoints — they require the storefront key header. A customer Bearer token is optional; when sent, it adds the <code>isInWishlist</code> / <code>isInCompare</code> flags. See <a href="/api/graphql-api/authentication.html">Authentication</a>.</p>',11)]))}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
